{
  "name": "Futsal Tapajós",
  "description": "Um placar eletrônico profissional e completo para partidas de futsal, com controle de gols, faltas, tempos técnicos e personalização total das equipes."
}

export type TeamSide = 'left' | 'right';

export interface TeamState {
  name: string;
  color: string;
  score: number;
  fouls: boolean[];
  timeouts: boolean[];
}

export interface ScoreboardState {
  leftTeam: TeamState;
  rightTeam: TeamState;
  time: number; // in seconds
  isRunning: boolean;
  period: number;
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useCallback } from 'react';
import { Settings, RefreshCw, Play, Pause, Plus, Minus, Edit2 } from 'lucide-react';
import { TeamState, TeamSide } from './types';
import TeamSection from './components/TeamSection';
import TimerDisplay from './components/TimerDisplay';
import SettingsModal from './components/SettingsModal';

const INITIAL_TEAM_LEFT: TeamState = {
  name: 'EQUIPE A',
  color: '#ef4444', // Red
  score: 0,
  fouls: Array(5).fill(false),
  timeouts: Array(2).fill(false),
};

const INITIAL_TEAM_RIGHT: TeamState = {
  name: 'EQUIPE B',
  color: '#3b82f6', // Blue
  score: 0,
  fouls: Array(5).fill(false),
  timeouts: Array(2).fill(false),
};

const App: React.FC = () => {
  const [leftTeam, setLeftTeam] = useState<TeamState>(INITIAL_TEAM_LEFT);
  const [rightTeam, setRightTeam] = useState<TeamState>(INITIAL_TEAM_RIGHT);
  const [time, setTime] = useState(1200); // 20 minutes in seconds
  const [isRunning, setIsRunning] = useState(false);
  const [period, setPeriod] = useState(1);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Timer logic
  useEffect(() => {
    let interval: number;
    if (isRunning && time > 0) {
      interval = window.setInterval(() => {
        setTime((prev) => prev - 1);
      }, 1000);
    } else if (time === 0) {
      setIsRunning(false);
    }
    return () => clearInterval(interval);
  }, [isRunning, time]);

  const toggleTimer = () => setIsRunning(!isRunning);

  const resetBoard = useCallback(() => {
    if (confirm('Tem certeza que deseja resetar o placar?')) {
      setLeftTeam(INITIAL_TEAM_LEFT);
      setRightTeam(INITIAL_TEAM_RIGHT);
      setTime(1200);
      setIsRunning(false);
      setPeriod(1);
    }
  }, []);

  const updateTeam = (side: TeamSide, updates: Partial<TeamState>) => {
    if (side === 'left') {
      setLeftTeam((prev) => ({ ...prev, ...updates }));
    } else {
      setRightTeam((prev) => ({ ...prev, ...updates }));
    }
  };

  const handleFoulToggle = (side: TeamSide, index: number) => {
    const team = side === 'left' ? leftTeam : rightTeam;
    const newFouls = [...team.fouls];
    newFouls[index] = !newFouls[index];
    updateTeam(side, { fouls: newFouls });
  };

  const handleTimeoutToggle = (side: TeamSide, index: number) => {
    const team = side === 'left' ? leftTeam : rightTeam;
    const newTimeouts = [...team.timeouts];
    newTimeouts[index] = !newTimeouts[index];
    updateTeam(side, { timeouts: newTimeouts });
  };

  const changeScore = (side: TeamSide, delta: number) => {
    const team = side === 'left' ? leftTeam : rightTeam;
    const newScore = Math.max(0, team.score + delta);
    updateTeam(side, { score: newScore });
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 md:p-8 bg-slate-950 text-white select-none">
      {/* Header / Brand */}
      <div className="mb-6 text-center">
        <h1 className="text-3xl md:text-5xl font-extrabold tracking-tighter text-blue-500 italic flex items-center gap-2">
          FUTSAL <span className="text-white">TAPAJÓS</span>
        </h1>
        <p className="text-slate-400 text-sm uppercase tracking-widest mt-1">Placar Eletrônico Oficial</p>
      </div>

      {/* Main Scoreboard Layout */}
      <div className="w-full max-w-6xl grid grid-cols-1 lg:grid-cols-3 gap-6 items-start">

        {/* Left Team */}
        <TeamSection 
          side="left"
          team={leftTeam}
          onScoreChange={(d) => changeScore('left', d)}
          onFoulToggle={(i) => handleFoulToggle('left', i)}
          onTimeoutToggle={(i) => handleTimeoutToggle('left', i)}
        />

        {/* Center: Clock & Controls */}
        <div className="flex flex-col items-center justify-between h-full py-4 space-y-8 bg-slate-900/50 rounded-3xl p-6 border border-slate-800 neon-border">
          <div className="text-center w-full">
            <span className="text-slate-500 font-semibold uppercase tracking-widest text-xs">Período</span>
            <div className="flex items-center justify-center gap-4 mt-2">
              <button 
                onClick={() => setPeriod(Math.max(1, period - 1))}
                className="p-1 rounded bg-slate-800 hover:bg-slate-700 transition"
              ><Minus size={16}/></button>
              <span className="text-4xl font-digital text-yellow-500">{period}º</span>
              <button 
                onClick={() => setPeriod(period + 1)}
                className="p-1 rounded bg-slate-800 hover:bg-slate-700 transition"
              ><Plus size={16}/></button>
            </div>
          </div>

          <TimerDisplay time={time} onTimeChange={setTime} />

          <div className="flex gap-4">
            <button 
              onClick={toggleTimer}
              className={`flex items-center gap-2 px-8 py-4 rounded-2xl font-bold text-lg transition-all ${
                isRunning 
                  ? 'bg-amber-600 hover:bg-amber-500 shadow-lg shadow-amber-900/20' 
                  : 'bg-emerald-600 hover:bg-emerald-500 shadow-lg shadow-emerald-900/20'
              }`}
            >
              {isRunning ? <Pause /> : <Play />}
              {isRunning ? 'PAUSAR' : 'INICIAR'}
            </button>
          </div>

          <div className="flex gap-3 mt-4">
             <button 
              onClick={() => setIsSettingsOpen(true)}
              className="p-3 bg-slate-800 rounded-full hover:bg-slate-700 transition"
              title="Configurações"
            >
              <Settings size={20} />
            </button>
            <button 
              onClick={resetBoard}
              className="p-3 bg-slate-800 rounded-full hover:bg-slate-700 transition"
              title="Resetar"
            >
              <RefreshCw size={20} />
            </button>
          </div>
        </div>

        {/* Right Team */}
        <TeamSection 
          side="right"
          team={rightTeam}
          onScoreChange={(d) => changeScore('right', d)}
          onFoulToggle={(i) => handleFoulToggle('right', i)}
          onTimeoutToggle={(i) => handleTimeoutToggle('right', i)}
        />
      </div>

      {/* Footer Instructions */}
      <div className="mt-8 text-slate-500 text-xs hidden md:block">
        Clique nos números para editar manualmente | Use os controles para gerenciar a partida
      </div>

      {/* Modals */}
      {isSettingsOpen && (
        <SettingsModal 
          isOpen={isSettingsOpen}
          onClose={() => setIsSettingsOpen(false)}
          leftTeam={leftTeam}
          rightTeam={rightTeam}
          onUpdateLeft={(u) => updateTeam('left', u)}
          onUpdateRight={(u) => updateTeam('right', u)}
        />
      )}
    </div>
  );
};

export default App;

import React from 'react';
import { Plus, Minus } from 'lucide-react';
import { TeamState } from '../types';

interface TeamSectionProps {
  side: 'left' | 'right';
  team: TeamState;
  onScoreChange: (delta: number) => void;
  onFoulToggle: (index: number) => void;
  onTimeoutToggle: (index: number) => void;
}

const TeamSection: React.FC<TeamSectionProps> = ({ 
  side, 
  team, 
  onScoreChange, 
  onFoulToggle, 
  onTimeoutToggle 
}) => {
  return (
    <div className={`flex flex-col space-y-6 ${side === 'right' ? 'lg:order-3' : 'lg:order-1'}`}>

      {/* Team Header */}
      <div 
        className="rounded-2xl p-6 border-b-4 text-center transition-all"
        style={{ backgroundColor: `${team.color}15`, borderBottomColor: team.color }}
      >
        <h2 className="text-2xl md:text-3xl font-black uppercase tracking-tight truncate px-2" style={{ color: team.color }}>
          {team.name}
        </h2>
      </div>

      {/* Score and Controls */}
      <div className="bg-slate-900 rounded-3xl p-8 flex flex-col items-center space-y-6 shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-1" style={{ backgroundColor: team.color }}></div>

        <span className="text-slate-500 font-bold uppercase tracking-widest text-xs">Gols</span>

        <div className="flex items-center gap-6">
          <button 
            onClick={() => onScoreChange(-1)}
            className="w-12 h-12 flex items-center justify-center bg-slate-800 hover:bg-slate-700 rounded-full transition-transform active:scale-95"
          >
            <Minus size={24} />
          </button>

          <div className="text-8xl md:text-9xl font-digital text-white font-bold min-w-[120px] text-center">
            {team.score}
          </div>

          <button 
            onClick={() => onScoreChange(1)}
            className="w-12 h-12 flex items-center justify-center bg-slate-800 hover:bg-slate-700 rounded-full transition-transform active:scale-95"
          >
            <Plus size={24} />
          </button>
        </div>
      </div>

      {/* Fouls and Timeouts Container */}
      <div className="grid grid-cols-2 gap-4">
        {/* Fouls */}
        <div className="bg-slate-900 rounded-2xl p-4 flex flex-col items-center space-y-3">
          <span className="text-slate-500 font-bold uppercase tracking-widest text-[10px]">Faltas</span>
          <div className="flex gap-1.5">
            {team.fouls.map((isSet, i) => (
              <div 
                key={i}
                onClick={() => onFoulToggle(i)}
                className={`w-4 h-6 md:w-5 md:h-8 rounded cursor-pointer transition-all ${
                  isSet 
                    ? 'bg-red-600 shadow-[0_0_10px_rgba(220,38,38,0.5)]' 
                    : 'bg-slate-800 hover:bg-slate-700'
                }`}
              />
            ))}
          </div>
        </div>

        {/* Timeouts */}
        <div className="bg-slate-900 rounded-2xl p-4 flex flex-col items-center space-y-3">
          <span className="text-slate-500 font-bold uppercase tracking-widest text-[10px]">Tempo</span>
          <div className="flex gap-2">
            {team.timeouts.map((isSet, i) => (
              <div 
                key={i}
                onClick={() => onTimeoutToggle(i)}
                className={`w-6 h-6 md:w-8 md:h-8 rounded-full border-2 cursor-pointer transition-all flex items-center justify-center ${
                  isSet 
                    ? 'bg-emerald-500 border-emerald-400 shadow-[0_0_10px_rgba(16,185,129,0.5)]' 
                    : 'border-slate-800 bg-slate-800/30'
                }`}
              >
                {isSet && <div className="w-2 h-2 rounded-full bg-white animate-pulse" />}
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default TeamSection;

import React, { useState, useEffect } from 'react';

interface TimerDisplayProps {
  time: number;
  onTimeChange: (newTime: number) => void;
}

const TimerDisplay: React.FC<TimerDisplayProps> = ({ time, onTimeChange }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editValue, setEditValue] = useState('');

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const handleManualEdit = (e: React.FormEvent) => {
    e.preventDefault();
    const [m, s] = editValue.split(':').map(Number);
    if (!isNaN(m) && !isNaN(s)) {
      onTimeChange(m * 60 + s);
    }
    setIsEditing(false);
  };

  return (
    <div className="flex flex-col items-center justify-center space-y-1">
      <span className="text-slate-500 font-bold uppercase tracking-widest text-xs">Cronômetro</span>
      {isEditing ? (
        <form onSubmit={handleManualEdit} className="relative">
          <input
            autoFocus
            type="text"
            className="bg-transparent border-b-2 border-yellow-500 text-5xl md:text-7xl font-digital text-yellow-500 text-center w-40 focus:outline-none"
            value={editValue}
            onChange={(e) => setEditValue(e.target.value)}
            onBlur={() => setIsEditing(false)}
            placeholder="20:00"
          />
        </form>
      ) : (
        <div 
          onClick={() => {
            setEditValue(formatTime(time));
            setIsEditing(true);
          }}
          className="text-6xl md:text-8xl font-digital text-yellow-500 cursor-pointer hover:opacity-80 transition-opacity drop-shadow-[0_0_10px_rgba(234,179,8,0.3)]"
        >
          {formatTime(time)}
        </div>
      )}
    </div>
  );
};

export default TimerDisplay;

import React from 'react';
import { X } from 'lucide-react';
import { TeamState } from '../types';

interface SettingsModalProps {
