    const team = side === 'left' ? leftTeam : rightTeam;
    const newScore = Math.max(0, team.score + delta);
    updateTeam(side, { score: newScore });
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-2 md:p-8 bg-slate-950 text-white select-none overflow-y-auto landscape:overflow-y-hidden">
      {/* Header / Brand - Hidden in mobile landscape to save space */}
      <div className="mb-4 md:mb-6 text-center landscape:hidden lg:landscape:block">
        <h1 className="text-2xl md:text-5xl font-extrabold tracking-tighter text-blue-500 italic flex items-center justify-center gap-2">
          FUTSAL <span className="text-white">TAPAJÓS</span>
        </h1>
        <p className="text-slate-400 text-[10px] md:text-sm uppercase tracking-widest mt-1">Placar Eletrônico Oficial</p>
      </div>

      {/* Main Scoreboard Layout */}
      <div className="w-full max-w-7xl grid grid-cols-1 landscape:grid-cols-3 lg:grid-cols-3 gap-2 md:gap-6 items-stretch">

        {/* Left Team */}
        <TeamSection 
          side="left"
          team={leftTeam}
          onScoreChange={(d) => changeScore('left', d)}
          onFoulToggle={(i) => handleFoulToggle('left', i)}
          onTimeoutToggle={(i) => handleTimeoutToggle('left', i)}
          onNameChange={(newName) => updateTeam('left', { name: newName })}
        />

        {/* Center: Clock & Controls */}
        <div className="flex flex-col items-center justify-between py-3 md:py-4 space-y-4 md:space-y-6 bg-slate-900/50 rounded-2xl md:rounded-3xl p-3 md:p-6 border border-slate-800 neon-border landscape:order-2">
          <div className="text-center w-full">
            <span className="text-slate-500 font-semibold uppercase tracking-widest text-[10px] md:text-xs">Período</span>
            <div className="flex items-center justify-center gap-3 md:gap-4 mt-1 md:mt-2">
              <button 
                onClick={() => setPeriod(Math.max(1, period - 1))}
                className="p-1 rounded bg-slate-800 hover:bg-slate-700 transition"
              ><Minus size={14}/></button>
              <span className="text-2xl md:text-4xl font-digital text-yellow-500">{period}º</span>
              <button 
                onClick={() => setPeriod(period + 1)}
                className="p-1 rounded bg-slate-800 hover:bg-slate-700 transition"
              ><Plus size={14}/></button>
            </div>
          </div>

          <TimerDisplay time={time} onTimeChange={setTime} />

          <div className="flex flex-col items-center gap-2 md:gap-4 w-full">
            <button 
              onClick={toggleTimer}
              className={`flex items-center justify-center gap-2 w-full md:w-auto px-6 md:px-10 py-3 md:py-4 rounded-xl md:rounded-2xl font-bold text-base md:text-lg transition-all ${
                isRunning 
                  ? 'bg-amber-600 hover:bg-amber-500 shadow-lg shadow-amber-900/20' 
                  : 'bg-emerald-600 hover:bg-emerald-500 shadow-lg shadow-emerald-900/20'
              }`}
            >
              {isRunning ? <Pause size={20}/> : <Play size={20}/>}
              {isRunning ? 'PAUSAR' : 'INICIAR'}
            </button>

            <div className="flex gap-2 md:gap-4">
              <button 
                onClick={resetTimer}
                className="p-2 md:p-3 bg-slate-800 rounded-full hover:bg-slate-700 transition group flex items-center gap-2"
                title="Resetar Tempo"
              >
                <RefreshCw size={18} className="text-yellow-500" />
                <span className="text-[10px] hidden md:block">Tempo</span>
              </button>

              <button 
                onClick={() => setIsSettingsOpen(true)}
                className="p-2 md:p-3 bg-slate-800 rounded-full hover:bg-slate-700 transition"
                title="Configurações"
              >
                <Settings size={18} />
              </button>

              <button 
                onClick={resetBoard}
                className="p-2 md:p-3 bg-slate-800 rounded-full hover:bg-red-900/30 border border-transparent hover:border-red-900/50 transition group flex items-center gap-2"
                title="Resetar Tudo"
              >
                <RefreshCw size={18} className="text-red-500 group-hover:rotate-180 transition-transform duration-500" />
                <span className="text-[10px] hidden md:block">Tudo</span>
              </button>
            </div>
          </div>
        </div>

        {/* Right Team */}
        <TeamSection 
          side="right"
          team={rightTeam}
          onScoreChange={(d) => changeScore('right', d)}
          onFoulToggle={(i) => handleFoulToggle('right', i)}
          onTimeoutToggle={(i) => handleTimeoutToggle('right', i)}
          onNameChange={(newName) => updateTeam('right', { name: newName })}
        />
      </div>

      {/* Modals */}
      {isSettingsOpen && (
        <SettingsModal 
          isOpen={isSettingsOpen}
          onClose={() => setIsSettingsOpen(false)}
          leftTeam={leftTeam}
          rightTeam={rightTeam}
          onUpdateLeft={(u) => updateTeam('left', u)}
          onUpdateRight={(u) => updateTeam('right', u)}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Plus, Minus, Edit2, Shield } from 'lucide-react';
import { TeamState } from '../types';

interface TeamSectionProps {
  side: 'left' | 'right';
  team: TeamState;
  onScoreChange: (delta: number) => void;
  onFoulToggle: (index: number) => void;
  onTimeoutToggle: (index: number) => void;
  onNameChange: (newName: string) => void;
}

const TeamSection: React.FC<TeamSectionProps> = ({ 
  side, 
  team, 
  onScoreChange, 
  onFoulToggle, 
  onTimeoutToggle,
  onNameChange
}) => {
  const [isEditingName, setIsEditingName] = useState(false);
  const [tempName, setTempName] = useState(team.name);

  const handleNameSubmit = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (tempName.trim()) {
      onNameChange(tempName.toUpperCase());
    } else {
      setTempName(team.name);
    }
    setIsEditingName(false);
  };

  return (
    <div className={`flex flex-col space-y-2 md:space-y-4 ${side === 'right' ? 'landscape:order-3' : 'landscape:order-1'}`}>

      {/* Team Header - Editable Name and Logo */}
      <div 
        className="rounded-xl md:rounded-2xl p-2 md:p-4 border-b-2 md:border-b-4 text-center transition-all group relative cursor-pointer min-h-[60px] md:min-h-[100px] flex items-center justify-center overflow-hidden"
        style={{ backgroundColor: `${team.color}15`, borderBottomColor: team.color }}
        onClick={() => !isEditingName && setIsEditingName(true)}
      >
        {isEditingName ? (
          <form onSubmit={handleNameSubmit} className="w-full">
            <input
              autoFocus
              type="text"
              className="bg-transparent border-b-2 border-white/20 text-lg md:text-2xl font-black uppercase tracking-tight text-center w-full focus:outline-none focus:border-white/50"
              style={{ color: team.color }}
              value={tempName}
              onChange={(e) => setTempName(e.target.value)}
              onBlur={() => handleNameSubmit()}
            />
          </form>
        ) : (
          <div className="flex items-center justify-center gap-2 md:gap-4 w-full">
            {team.logo ? (
              <img src={team.logo} alt="Logo" className="w-8 h-8 md:w-14 md:h-14 object-contain" />
            ) : (
              <Shield size={24} className="md:size-32 opacity-20" style={{ color: team.color }} />
            )}

            <h2 className="text-lg md:text-3xl font-black uppercase tracking-tight truncate px-1 md:px-2 flex-1" style={{ color: team.color }}>
              {team.name}
            </h2>
            <Edit2 size={12} className="opacity-0 group-hover:opacity-50 transition-opacity absolute right-2" style={{ color: team.color }} />
          </div>
        )}
      </div>

      {/* Score and Controls */}
      <div className="bg-slate-900 rounded-2xl md:rounded-3xl p-3 md:p-6 flex flex-col items-center space-y-2 md:space-y-4 shadow-xl relative overflow-hidden flex-1 justify-center min-h-[140px] md:min-h-[200px]">
        <div className="absolute top-0 left-0 w-full h-1" style={{ backgroundColor: team.color }}></div>

        <span className="text-slate-500 font-bold uppercase tracking-widest text-[10px] md:text-xs">Gols</span>

        <div className="flex items-center gap-3 md:gap-6">
          <button 
            onClick={(e) => { e.stopPropagation(); onScoreChange(-1); }}
            className="w-8 h-8 md:w-12 md:h-12 flex items-center justify-center bg-slate-800 hover:bg-slate-700 rounded-full transition-transform active:scale-95"
          >
            <Minus size={16} />
          </button>

          <div className="text-6xl md:text-9xl font-digital text-white font-bold min-w-[70px] md:min-w-[120px] text-center">
            {team.score}
          </div>

          <button 
            onClick={(e) => { e.stopPropagation(); onScoreChange(1); }}
            className="w-8 h-8 md:w-12 md:h-12 flex items-center justify-center bg-slate-800 hover:bg-slate-700 rounded-full transition-transform active:scale-95"
          >
            <Plus size={16} />
          </button>
        </div>
      </div>

      {/* Fouls and Timeouts Container */}
      <div className="grid grid-cols-2 gap-2 md:gap-4">
        {/* Fouls */}
        <div className="bg-slate-900 rounded-xl md:rounded-2xl p-2 md:p-3 flex flex-col items-center space-y-1 md:space-y-2">
          <span className="text-slate-500 font-bold uppercase tracking-widest text-[8px] md:text-[10px]">Faltas</span>
          <div className="flex gap-1 md:gap-1.5">
            {team.fouls.map((isSet, i) => (
              <div 
                key={i}
                onClick={() => onFoulToggle(i)}
                className={`w-3 h-5 md:w-5 md:h-8 rounded cursor-pointer transition-all ${
                  isSet 
                    ? 'bg-red-600 shadow-[0_0_8px_rgba(220,38,38,0.5)]' 
                    : 'bg-slate-800 hover:bg-slate-700'
                }`}
              />
            ))}
          </div>
        </div>

        {/* Timeouts */}
        <div className="bg-slate-900 rounded-xl md:rounded-2xl p-2 md:p-3 flex flex-col items-center space-y-1 md:space-y-2">
          <span className="text-slate-500 font-bold uppercase tracking-widest text-[8px] md:text-[10px]">Tempo</span>
          <div className="flex gap-1 md:gap-2">
            {team.timeouts.map((isSet, i) => (
              <div 
                key={i}
                onClick={() => onTimeoutToggle(i)}
                className={`w-4 h-4 md:w-8 md:h-8 rounded-full border-2 cursor-pointer transition-all flex items-center justify-center ${
                  isSet 
                    ? 'bg-emerald-500 border-emerald-400 shadow-[0_0_8px_rgba(16,185,129,0.5)]' 
                    : 'border-slate-800 bg-slate-800/30'
                }`}
              >
                {isSet && <div className="w-1.5 h-1.5 md:w-2 h-2 rounded-full bg-white animate-pulse" />}
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default TeamSection;

import React, { useRef } from 'react';
import { X, Upload, Image as ImageIcon } from 'lucide-react';
import { TeamState } from '../types';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  leftTeam: TeamState;
  rightTeam: TeamState;
  onUpdateLeft: (updates: Partial<TeamState>) => void;
  onUpdateRight: (updates: Partial<TeamState>) => void;
}

const COLORS = [
  '#ef4444', // Red
  '#3b82f6', // Blue
  '#22c55e', // Green
  '#eab308', // Yellow
  '#a855f7', // Purple
  '#f97316', // Orange
  '#ffffff', // White
  '#000000', // Black
];

const SettingsModal: React.FC<SettingsModalProps> = ({ 
  onClose, 
  leftTeam, 
  rightTeam, 
  onUpdateLeft, 
  onUpdateRight 
}) => {
  const leftInputRef = useRef<HTMLInputElement>(null);
  const rightInputRef = useRef<HTMLInputElement>(null);

  const handleImageUpload = (side: 'left' | 'right', e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        if (side === 'left') {
          onUpdateLeft({ logo: base64String });
        } else {
          onUpdateRight({ logo: base64String });
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const TeamConfig = ({ team, onUpdate, inputRef, side }: { team: TeamState, onUpdate: (u: Partial<TeamState>) => void, inputRef: React.RefObject<HTMLInputElement>, side: 'left' | 'right' }) => (
    <div className="space-y-6 bg-slate-800/30 p-4 rounded-2xl border border-slate-700/50">
      <h3 className="text-sm font-bold uppercase tracking-widest text-slate-500">Equipe {side === 'left' ? 'Lado Esquerdo' : 'Lado Direito'}</h3>
      <div className="space-y-4">
        {/* Name */}
        <div>
          <label className="block text-xs mb-1 text-slate-400">Nome da Equipe</label>
          <input 
            type="text" 
            value={team.name}
            onChange={(e) => onUpdate({ name: e.target.value })}
            className="w-full bg-slate-800 border border-slate-700 rounded-lg px-4 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
          />
        </div>

        {/* Logo Upload */}
        <div>
          <label className="block text-xs mb-2 text-slate-400">Escudo da Equipe</label>
          <div className="flex items-center gap-4">
            <div 
              className="w-16 h-16 rounded-xl bg-slate-800 border-2 border-dashed border-slate-600 flex items-center justify-center overflow-hidden cursor-pointer hover:border-blue-500 transition-colors"
              onClick={() => inputRef.current?.click()}
            >
              {team.logo ? (
                <img src={team.logo} alt="Preview" className="w-full h-full object-contain" />
              ) : (
                <ImageIcon className="text-slate-500" size={24} />
              )}
            </div>
            <button 
              onClick={() => inputRef.current?.click()}
              className="flex items-center gap-2 text-xs bg-slate-700 hover:bg-slate-600 px-3 py-2 rounded-lg transition-colors"
            >
              <Upload size={14} />
              Carregar Imagem
            </button>
            <input 
              type="file" 
              ref={inputRef}
              hidden 
              accept="image/*"
              onChange={(e) => handleImageUpload(side, e)}
            />
          </div>
        </div>

        {/* Colors */}
        <div>
          <label className="block text-xs mb-2 text-slate-400">Cor Principal</label>
          <div className="flex flex-wrap gap-2">
            {COLORS.map(c => (
              <button 
                key={c}
                onClick={() => onUpdate({ color: c })}
                className={`w-8 h-8 rounded-full border-2 transition-transform hover:scale-110 ${team.color === c ? 'border-white scale-110' : 'border-transparent'}`}
                style={{ backgroundColor: c }}
              />
            ))}
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-slate-900 border border-slate-800 rounded-3xl w-full max-w-4xl overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
        <div className="flex items-center justify-between p-6 border-b border-slate-800">
          <h2 className="text-xl font-bold flex items-center gap-2">Configurações das Equipes</h2>
          <button onClick={onClose} className="p-2 hover:bg-slate-800 rounded-full transition">
            <X size={24} />
          </button>
        </div>

        <div className="p-6 md:p-8 grid grid-cols-1 md:grid-cols-2 gap-6 md:gap-10 overflow-y-auto">
          <TeamConfig side="left" team={leftTeam} onUpdate={onUpdateLeft} inputRef={leftInputRef} />
          <TeamConfig side="right" team={rightTeam} onUpdate={onUpdateRight} inputRef={rightInputRef} />
        </div>

        <div className="p-6 bg-slate-800/50 flex justify-end">
          <button 
            onClick={onClose}
            className="bg-blue-600 hover:bg-blue-500 text-white px-8 py-3 rounded-xl font-bold transition-all shadow-lg shadow-blue-900/20 w-full md:w-auto"
          >
            SALVAR ALTERAÇÕES
          </button>
        </div>
      </div>
    </div>
  );
};

export default SettingsModal;

import React, { useState, useEffect, useCallback } from 'react';
import { Settings, RefreshCw, Play, Pause, Plus, Minus, TimerReset } from 'lucide-react';
import { TeamState, TeamSide } from './types';
import TeamSection from './components/TeamSection';
import TimerDisplay from './components/TimerDisplay';
import SettingsModal from './components/SettingsModal';

const INITIAL_TEAM_LEFT: TeamState = {
  name: 'EQUIPE A',
  color: '#ef4444', // Red
  score: 0,
  fouls: Array(5).fill(false),
  timeouts: Array(2).fill(false),
};

const INITIAL_TEAM_RIGHT: TeamState = {
  name: 'EQUIPE B',
  color: '#3b82f6', // Blue
  score: 0,
  fouls: Array(5).fill(false),
  timeouts: Array(2).fill(false),
};

const App: React.FC = () => {
  const [leftTeam, setLeftTeam] = useState<TeamState>(INITIAL_TEAM_LEFT);
  const [rightTeam, setRightTeam] = useState<TeamState>(INITIAL_TEAM_RIGHT);
  const [time, setTime] = useState(1200); // 20 minutes in seconds
  const [isRunning, setIsRunning] = useState(false);
  const [period, setPeriod] = useState(1);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  useEffect(() => {
    let interval: number;
    if (isRunning && time > 0) {
      interval = window.setInterval(() => {
        setTime((prev) => prev - 1);
      }, 1000);
    } else if (time === 0) {
      setIsRunning(false);
    }
    return () => clearInterval(interval);
  }, [isRunning, time]);

  const toggleTimer = () => setIsRunning(!isRunning);

  const resetTimer = useCallback(() => {
    if (confirm('Deseja reiniciar apenas o cronômetro para 20:00?')) {
      setTime(1200);
      setIsRunning(false);
    }
  }, []);

  const resetBoard = useCallback(() => {
    if (confirm('Tem certeza que deseja resetar TUDO (placar, faltas e tempo)?')) {
      setLeftTeam(INITIAL_TEAM_LEFT);
      setRightTeam(INITIAL_TEAM_RIGHT);
      setTime(1200);
      setIsRunning(false);
      setPeriod(1);
    }
  }, []);

  const updateTeam = (side: TeamSide, updates: Partial<TeamState>) => {
    if (side === 'left') {
      setLeftTeam((prev) => ({ ...prev, ...updates }));
    } else {
      setRightTeam((prev) => ({ ...prev, ...updates }));
    }
  };

  const handleFoulToggle = (side: TeamSide, index: number) => {
    const team = side === 'left' ? leftTeam : rightTeam;
    const newFouls = [...team.fouls];
    newFouls[index] = !newFouls[index];
    updateTeam(side, { fouls: newFouls });
  };

  const handleTimeoutToggle = (side: TeamSide, index: number) => {
    const team = side === 'left' ? leftTeam : rightTeam;
    const newTimeouts = [...team.timeouts];
    newTimeouts[index] = !newTimeouts[index];
    updateTeam(side, { timeouts: newTimeouts });
  };

  const changeScore = (side: TeamSide, delta: number) => {
    const team = side === 'left' ? leftTeam : rightTeam;
    const newScore = Math.max(0, team.score + delta);
    updateTeam(side, { score: newScore });
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-2 md:p-8 bg-slate-950 text-white select-none overflow-y-auto landscape:overflow-y-hidden">
      {/* Header / Brand - Hidden in mobile landscape to save space */}
      <div className="mb-4 md:mb-6 text-center landscape:hidden lg:landscape:block">
        <h1 className="text-2xl md:text-5xl font-extrabold tracking-tighter text-blue-500 italic flex items-center justify-center gap-2">
          FUTSAL <span className="text-white">TAPAJÓS</span>
        </h1>
        <p className="text-slate-400 text-[10px] md:text-sm uppercase tracking-widest mt-1">Placar Eletrônico Oficial</p>
      </div>

      {/* Main Scoreboard Layout */}
      <div className="w-full max-w-7xl grid grid-cols-1 landscape:grid-cols-[1fr_0.8fr_1fr] lg:grid-cols-[1fr_0.8fr_1fr] gap-2 md:gap-6 items-stretch">

        {/* Left Team */}
        <TeamSection 
          side="left"
          team={leftTeam}
          onScoreChange={(d) => changeScore('left', d)}
          onFoulToggle={(i) => handleFoulToggle('left', i)}
          onTimeoutToggle={(i) => handleTimeoutToggle('left', i)}
          onNameChange={(newName) => updateTeam('left', { name: newName })}
        />

        {/* Center: Clock & Controls */}
        <div className="flex flex-col items-center justify-between py-3 md:py-4 space-y-4 md:space-y-6 bg-slate-900/50 rounded-2xl md:rounded-3xl p-3 md:p-6 border border-slate-800 neon-border landscape:order-2">
          <div className="text-center w-full">
            <span className="text-slate-500 font-semibold uppercase tracking-widest text-[10px] md:text-xs">Período</span>
            <div className="flex items-center justify-center gap-3 md:gap-4 mt-1 md:mt-2">
              <button 
                onClick={() => setPeriod(Math.max(1, period - 1))}
                className="p-1 rounded bg-slate-800 hover:bg-slate-700 transition"
              ><Minus size={14}/></button>
              <span className="text-2xl md:text-4xl font-digital text-yellow-500">{period}º</span>
              <button 
                onClick={() => setPeriod(period + 1)}
                className="p-1 rounded bg-slate-800 hover:bg-slate-700 transition"
              ><Plus size={14}/></button>
            </div>
          </div>

          <TimerDisplay time={time} onTimeChange={setTime} onReset={resetTimer} />

          <div className="flex flex-col items-center gap-2 md:gap-4 w-full">
            <button 
              onClick={toggleTimer}
              className={`flex items-center justify-center gap-2 w-full md:w-auto px-6 md:px-10 py-3 md:py-4 rounded-xl md:rounded-2xl font-bold text-base md:text-lg transition-all ${
                isRunning 
                  ? 'bg-amber-600 hover:bg-amber-500 shadow-lg shadow-amber-900/20' 
                  : 'bg-emerald-600 hover:bg-emerald-500 shadow-lg shadow-emerald-900/20'
              }`}
            >
              {isRunning ? <Pause size={20}/> : <Play size={20}/>}
              {isRunning ? 'PAUSAR' : 'INICIAR'}
            </button>

            <div className="flex gap-2 md:gap-4">
              <button 
                onClick={resetTimer}
                className="p-2 md:p-3 bg-slate-800 rounded-full hover:bg-slate-700 transition group flex items-center gap-2 border border-yellow-500/20"
                title="Resetar Tempo"
              >
                <TimerReset size={18} className="text-yellow-500 group-hover:rotate-[-45deg] transition-transform" />
                <span className="text-[10px] hidden md:block">Tempo</span>
              </button>

              <button 
                onClick={() => setIsSettingsOpen(true)}
                className="p-2 md:p-3 bg-slate-800 rounded-full hover:bg-slate-700 transition border border-slate-700"
                title="Configurações"
              >
                <Settings size={18} />
              </button>

              <button 
                onClick={resetBoard}
                className="p-2 md:p-3 bg-slate-800 rounded-full hover:bg-red-900/30 border border-red-500/20 transition group flex items-center gap-2"
                title="Resetar Tudo"
              >
                <RefreshCw size={18} className="text-red-500 group-hover:rotate-180 transition-transform duration-500" />
                <span className="text-[10px] hidden md:block">Tudo</span>
              </button>
            </div>
          </div>
        </div>

        {/* Right Team */}
        <TeamSection 
          side="right"
          team={rightTeam}
          onScoreChange={(d) => changeScore('right', d)}
          onFoulToggle={(i) => handleFoulToggle('right', i)}
          onTimeoutToggle={(i) => handleTimeoutToggle('right', i)}
          onNameChange={(newName) => updateTeam('right', { name: newName })}
